// Loop over input items to separate Google and YouTube results
const googleResults = items.find(item => item.json.search_parameters && item.json.search_parameters.engine === 'google');
const youtubeResults = items.find(item => item.json.search_parameters && item.json.search_parameters.engine === 'youtube');

// Dynamically extract the topic from the search parameters
// We prefer the Google query 'q', but fall back to YouTube 'search_query' if needed
let topic = "Unknown Topic";
if (googleResults && googleResults.json.search_parameters.q) {
  topic = googleResults.json.search_parameters.q;
} else if (youtubeResults && youtubeResults.json.search_parameters.search_query) {
  topic = youtubeResults.json.search_parameters.search_query;
}

// Prepare the consolidated data object
const consolidatedData = {
  topic: topic,
  google: {
    total_results: googleResults ? googleResults.json.search_information.total_results : 0,
    organic_results: googleResults ? googleResults.json.organic_results : [],
    // You can add more Google fields here if needed
  },
  youtube: {
    total_results: youtubeResults ? youtubeResults.json.search_information.total_results : 0,
    video_results: youtubeResults ? youtubeResults.json.video_results : [],
    shorts_results: youtubeResults ? youtubeResults.json.shorts_results : []
  },
  google_total: googleResults ? googleResults.json.search_information.total_results : 0,
  youtube_total: youtubeResults ? youtubeResults.json.search_information.total_results : 0
};

// Return the data in the specific format requested
// Note: We stringify 'consolidated_serp' because your output example showed it as a string
return [
  {
    json: {
      topic: topic,
      consolidated_serp: JSON.stringify(consolidatedData, null, 2)
    }
  }
];

// Loop through all input items
for (const item of items) {
  const text = item.json.text || "";

  // --- ROBUST DATA FETCHING ---
  // We grab both the 'topic' and the 'row_number' directly from the source node
  let searchKey = "Unknown";
  let rowNum = "";

  try {
    // Access the original source node
    const sourceItems = $('Get row(s) in sheet').all();
    // Match by index (assumes 1-to-1 processing)
    const sourceItem = sourceItems[item.index] || sourceItems[0];

    searchKey = sourceItem.json["Search Query"] || sourceItem.json.topic;
    rowNum = sourceItem.json.row_number; 
  } catch (e) {
    console.log("Could not fetch source data");
  }

  // --- PARSING LOGIC ---
  function getVal(block, label) {
    if (!block) return "";
    const regex = new RegExp(`\\*\\*${label}\\*\\*:\\s*(.*)`);
    const match = block.match(regex);
    return match ? match[1].trim() : "";
  }

  const sections = text.split(/## \d\. |# VERDICT/);
  const termSection = sections.find(s => s.includes("THE TERMINOLOGY CHECK")) || "";
  const satSection = sections.find(s => s.includes("THE SATURATION CHECK")) || "";
  const velSection = sections.find(s => s.includes("THE VELOCITY CHECK")) || "";
  const verdictSection = sections.find(s => s.includes("Recommendation")) || sections[sections.length - 1] || "";

  // Output Object
  item.json = {
    "row_number": rowNum, // <--- CRITICAL FOR UPDATING
    "Search Query": searchKey, 
    "User Terms": getVal(termSection, "User Terms"),
    "Google Organic Terms": getVal(termSection, "Google Organic \\(Top 5\\)"),
    "YouTube Terms": getVal(termSection, "YouTube \\(Top 5 by views\\)"),
    "Saturation Score": getVal(satSection, "Saturation Score"),
    "Saturation Reasoning": getVal(satSection, "Reasoning"),
    "Outlier Video": getVal(velSection, "Outlier Video"),
    "Velocity Stats": getVal(velSection, "Stats"),
    "Why It Won": getVal(velSection, "Why it won"),
    "Verdict Recommendation": getVal(verdictSection, "Recommendation"),
    "Verdict Confidence": getVal(verdictSection, "Confidence Score"),
    "Verdict Reasoning": getVal(verdictSection, "Reasoning"),
    "Key Market Signals": verdictSection.includes("Key Market Signals") ? verdictSection.split("Key Market Signals for Content**:")[1].replace(/\n/g, " ").trim() : ""
  };
}
return items;

// Loop through all input items
for (const item of items) {
  const text = item.json.text || "";

  // --- ROBUST DATA FETCHING ---
  let searchKey = "Unknown";
  let rowNum = "";
  try {
    const sourceItems = $('Get row(s) in sheet').all();
    const sourceItem = sourceItems[item.index] || sourceItems[0];
    searchKey = sourceItem.json["Search Query"] || sourceItem.json.topic;
    rowNum = sourceItem.json.row_number; 
  } catch (e) {
    console.log("Could not fetch source data");
  }

  // --- PARSING LOGIC (Fixed for Headers) ---
  const sections = text.split(/(?:^|\n)#{1,6}\s+/);
  let pivot = "", titles = "", thumbnails = "", hook = "", teaser = "";

  sections.forEach(section => {
    const cleanSec = section.trim();
    if (cleanSec.match(/^1\.\s*THE PIVOT/i)) pivot = cleanSec.replace(/^1\.\s*THE PIVOT.*(\n|$)/i, "").trim();
    else if (cleanSec.match(/^2\.\s*YOUTUBE TITLES/i)) titles = cleanSec.replace(/^2\.\s*YOUTUBE TITLES.*(\n|$)/i, "").trim();
    else if (cleanSec.match(/^3\.\s*THUMBNAIL TEXT/i)) thumbnails = cleanSec.replace(/^3\.\s*THUMBNAIL TEXT.*(\n|$)/i, "").trim();
    else if (cleanSec.match(/^4\.\s*DESCRIPTION HOOK/i)) hook = cleanSec.replace(/^4\.\s*DESCRIPTION HOOK.*(\n|$)/i, "").trim();
    else if (cleanSec.match(/^5\.\s*SOCIAL TEASER/i)) teaser = cleanSec.replace(/^5\.\s*SOCIAL TEASER.*(\n|$)/i, "").trim();
  });

  // Output Object
  item.json = {
    "row_number": rowNum, // <--- CRITICAL FOR UPDATING
    "Search Query": searchKey,
    "Pivot Strategy": pivot,
    "YouTube Titles": titles,       
    "Thumbnail Options": thumbnails, 
    "Description Hook": hook,
    "Social Teaser": teaser
  };
}
return items;
